namespace mtp_eth
{
  inline app::bring_up_result g_up{};

  inline const char*
  fmt (const char* format, unsigned a, unsigned b = 0)
  {
    static char text[128];
    std::snprintf (text, sizeof (text), format, a, b);
    return text;
  }

  inline const char*
  fmt_str (const char* format, const char* s)
  {
    static char text[128];
    std::snprintf (text, sizeof (text), format, s != nullptr ? s : "");
    return text;
  }

  inline const char*
  fmt_ip (const char* label, std::uint32_t ip)
  {
    static char text[128];
    std::snprintf (text, sizeof (text), "%s: %u.%u.%u.%u", label,
                   static_cast<unsigned> ((ip >> 24) & 0xffu),
                   static_cast<unsigned> ((ip >> 16) & 0xffu),
                   static_cast<unsigned> ((ip >> 8) & 0xffu),
                   static_cast<unsigned> (ip & 0xffu));
    return text;
  }
} // namespace mtp_eth
